import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';
import { ErrorBoundary } from './components/ErrorBoundary';
import './styles/globals.css';
import { clearAuthAndRedirect } from './config';

const rootEl = document.getElementById('app-main') || document.getElementById('root');

if (rootEl) {
  // Wrap global fetch so any 401 from API triggers auth clear + redirect to signin.
  // This ensures hosted preview pages gracefully redirect users to sign-in
  // instead of silently failing with repeated 401 errors.
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  if (typeof window !== 'undefined' && (window as any).fetch) {
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const _origFetch = (window as any).fetch;
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    (window as any).fetch = async function (input: any, init?: any) {
      try {
        const resp = await _origFetch(input, init);
        try {
          if (resp && resp.status === 401) {
            clearAuthAndRedirect();
          }
        } catch (e) {
          // ignore
        }
        return resp;
      } catch (e) {
        throw e;
      }
    };
  }
  const root = ReactDOM.createRoot(rootEl);
  root.render(
    <React.StrictMode>
      <ErrorBoundary>
        <App />
      </ErrorBoundary>
    </React.StrictMode>
  );
}

import { useState, useEffect, useCallback } from 'react';

export interface Route {
  view: string;
  params: Record<string, string>;
}

export function getCurrentRoute(): Route {
  let pathStr = '';
  let queryStr = '';

  // Prefer hash-based routing (#/view)
  const hash = window.location.hash.slice(1);
  if (hash && hash.length > 1) {
    const [hPath, hQuery] = hash.split('?');
    pathStr = hPath;
    queryStr = hQuery || '';
  } else {
    // Fall back to path-based routing (e.g. /dashboard/repository-health)
    const fullPath = window.location.pathname;
    // Strip /dashboard prefix if present
    let cleaned = fullPath;
    if (cleaned.startsWith('/dashboard')) {
      cleaned = cleaned.slice('/dashboard'.length);
    }
    // Strip leading slash
    cleaned = cleaned.replace(/^\//, '');
    if (cleaned) {
      pathStr = '/' + cleaned;
      queryStr = window.location.search.slice(1);
    }
  }

  const segments = pathStr.split('/').filter(Boolean);
  const view = segments[0] || 'dashboard';
  const params: Record<string, string> = {};

  if (queryStr) {
    new URLSearchParams(queryStr).forEach((value: string, key: string) => {
      params[key] = value;
    });
  }

  if (segments[1]) {
    params.mode = segments[1];
  }

  return { view, params };
}

export function navigate(view: string, params?: Record<string, string>) {
  let hash = `/${view}`;
  if (params?.mode) {
    hash += `/${params.mode}`;
  }
  const searchParams = new URLSearchParams();
  if (params) {
    Object.entries(params).forEach(([key, value]) => {
      if (key !== 'mode') searchParams.set(key, value);
    });
  }
  const qs = searchParams.toString();
  if (qs) hash += `?${qs}`;
  window.location.hash = hash;
  try {
    // Ensure scroll resets for embedded hosts
    const sc = document.querySelector('#app-main') || document.querySelector('.app-main') || document.scrollingElement || document.documentElement;
    if (sc && typeof (sc as any).scrollTo === 'function') (sc as any).scrollTo(0, 0); else if (typeof window.scrollTo === 'function') window.scrollTo(0, 0);
  } catch (e) { /* ignore */ }
}

export function useHashRoute() {
  const [route, setRoute] = useState(getCurrentRoute());

  // simplebeacon-ignore: framework-practices — standard React useEffect hook
  useEffect(() => {
    const onHashChange = () => setRoute(getCurrentRoute());
    window.addEventListener('hashchange', onHashChange);
    return () => window.removeEventListener('hashchange', onHashChange);
  }, []);

  const handleNavigate = useCallback((view: string, params?: Record<string, string>) => {
    navigate(view, params);
    setRoute(getCurrentRoute());
    try {
      const sc = document.querySelector('#app-main') || document.querySelector('.app-main') || document.scrollingElement || document.documentElement;
      if (sc && typeof (sc as any).scrollTo === 'function') (sc as any).scrollTo(0, 0); else if (typeof window.scrollTo === 'function') window.scrollTo(0, 0);
    } catch (e) { /* ignore */ }
  }, []);

  return { route, navigate: handleNavigate };
}

export async function checkLocalNetworkAccess(apiBase: string, timeoutMs = 2000): Promise<boolean> {
  if (!apiBase) return false;
  try {
    const url = `${apiBase.replace(/\/+$/, '')}/api/health`;
    const controller = new AbortController();
    const id = setTimeout(() => controller.abort(), timeoutMs);
    const res = await fetch(url, {
      method: 'GET',
      mode: 'cors',
      signal: controller.signal
    });
    clearTimeout(id);
    return res.ok || res.status === 401 || res.status === 403 || res.status === 404;
  } catch {
    return false;
  }
}

export function isLoopbackHost(apiBase: string): boolean {
  try {
    const u = new URL(apiBase);
    return /^(127\.0\.0\.1|localhost|\[::1\])$/.test(u.hostname);
  } catch {
    return false;
  }
}

