    </Card>
  );
}

import { useState, useCallback, useEffect } from 'react';
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from '@/components/ui/card';
import { Badge } from '@/components/ui/badge';
import { Button } from '@/components/ui/button';
import { BarChart3, RefreshCw, AlertCircle, Server, Activity, Cpu, HardDrive, Globe, Zap, CheckCircle2 } from 'lucide-react';
import { apiUrl, authHeaders } from '@/config';

type PlatformStatus = {
  platform?: string;
  status?: string;
  features?: Record<string, string>;
  statistics?: {
    files_processed?: number | string;
    consolidation_complete?: boolean;
    reduction_rate?: string;
    [key: string]: unknown;
  };
};

type HealthStatus = {
  status?: string;
  timestamp?: string;
  platform?: string;
  version?: string;
};

export function PlatformView() {
  const [platformData, setPlatformData] = useState<PlatformStatus | null>(null);
  const [healthData, setHealthData] = useState<HealthStatus | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const fetchData = useCallback(async () => {
    setLoading(true);
    setError(null);
    try {
      const [statusResp, healthResp] = await Promise.allSettled([
        fetch(apiUrl('/status'), { headers: authHeaders() }),
        fetch(apiUrl('/health'), { headers: authHeaders() }),
      ]);

      if (statusResp.status === 'fulfilled' && statusResp.value.ok) {
        setPlatformData(await statusResp.value.json());
      }
      if (healthResp.status === 'fulfilled' && healthResp.value.ok) {
        setHealthData(await healthResp.value.json());
      }

      if (statusResp.status === 'rejected' && healthResp.status === 'rejected') {
        throw new Error('Failed to fetch platform data');
      }
    } catch (e: any) {
      setError(e?.message || 'Failed to fetch platform data');
    } finally {
      setLoading(false);
    }
  }, []);

  // fetch on mount
  useEffect(() => { void fetchData(); }, [fetchData]);

  if (loading) {
    return (
      <div className="mx-auto max-w-5xl p-6 space-y-6">
        <div className="flex flex-col gap-2">
          <h1 className="text-3xl font-bold tracking-tight">Platform</h1>
          <p className="text-foreground-muted">Platform analytics and deployment metrics</p>
        </div>
        <Card>
          <CardContent className="flex flex-col items-center gap-3 py-12">
            <RefreshCw className="h-8 w-8 text-foreground-muted animate-spin" />
            <p className="text-sm text-foreground-muted">Loading platform data…</p>
          </CardContent>
        </Card>
      </div>
    );
  }

  if (error && !platformData && !healthData) {
    return (
      <div className="mx-auto max-w-5xl p-6 space-y-6">
        <div className="flex flex-col gap-2">
          <h1 className="text-3xl font-bold tracking-tight">Platform</h1>
          <p className="text-foreground-muted">Platform analytics and deployment metrics</p>
        </div>
        <Card>
          <CardContent className="flex flex-col items-center gap-3 py-12">
            <AlertCircle className="h-12 w-12 text-foreground-muted" />
            <p className="text-sm text-foreground-muted">{error}</p>
            <Button size="sm" onClick={fetchData} className="mt-2">
              <RefreshCw className="h-4 w-4 mr-2" /> Retry
            </Button>
          </CardContent>
        </Card>
      </div>
    );
  }

  const features = platformData?.features || {};
  const stats = platformData?.statistics || {};

  const featureIcons: Record<string, typeof Server> = {
    ai_scan: Cpu,
    web_interface: Globe,
    api_endpoints: Zap,
    tools: Server,
  };

  return (
    <div className="mx-auto max-w-5xl p-6 space-y-6">
      <div className="flex flex-col gap-2">
        <h1 className="text-3xl font-bold tracking-tight">Platform</h1>
        <p className="text-foreground-muted">Platform analytics and deployment metrics</p>
        <div className="flex items-center gap-2">
          {healthData?.status && (
            <Badge variant={healthData.status === 'healthy' ? 'success' : 'warning'}>
              {healthData.status}
            </Badge>
          )}
          {healthData?.version && (
            <Badge variant="outline">v{healthData.version}</Badge>
          )}
          <Button size="sm" variant="outline" onClick={fetchData}>
            <RefreshCw className="h-4 w-4" /> Refresh
          </Button>
        </div>
      </div>

      {/* System Health */}
      <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
        <Card>
          <CardContent className="flex flex-col items-center gap-1 py-4">
            <Server className="h-6 w-6 text-foreground-muted" />
            <span className="text-lg font-bold">{platformData?.platform || 'Simplebeacon'}</span>
            <span className="text-xs text-foreground-muted">Platform</span>
          </CardContent>
        </Card>
        <Card>
          <CardContent className="flex flex-col items-center gap-1 py-4">
            <Activity className="h-6 w-6 text-green-500" />
            <span className="text-lg font-bold capitalize">{platformData?.status || healthData?.status || '—'}</span>
            <span className="text-xs text-foreground-muted">Status</span>
          </CardContent>
        </Card>
        <Card>
          <CardContent className="flex flex-col items-center gap-1 py-4">
            <HardDrive className="h-6 w-6 text-foreground-muted" />
            <span className="text-lg font-bold">{String(stats.files_processed ?? '—')}</span>
            <span className="text-xs text-foreground-muted">Files Processed</span>
          </CardContent>
        </Card>
        <Card>
          <CardContent className="flex flex-col items-center gap-1 py-4">
            <BarChart3 className="h-6 w-6 text-foreground-muted" />
            <span className="text-lg font-bold">{stats.reduction_rate || '—'}</span>
            <span className="text-xs text-foreground-muted">Reduction Rate</span>
          </CardContent>
        </Card>
      </div>

      {/* Features */}
      {Object.keys(features).length > 0 && (
        <Card>
          <CardHeader>
            <CardTitle className="text-lg">Platform Features</CardTitle>
          </CardHeader>
          <CardContent className="grid gap-3 md:grid-cols-2">
            {Object.entries(features).map(([key, value]) => {
              const Icon = featureIcons[key] || CheckCircle2;
              return (
                <div key={key} className="flex items-center gap-3 rounded-lg border p-3">
                  <Icon className="h-5 w-5 text-foreground-muted" />
                  <div className="flex-1">
                    <span className="text-sm font-medium capitalize">{key.replace(/_/g, ' ')}</span>
                  </div>
                  <Badge variant={value === 'ready' || value === 'active' || value === 'available' ? 'success' : 'outline'}>
                    {value}
                  </Badge>
                </div>
              );
            })}
          </CardContent>
        </Card>
      )}

      {/* Health Details */}
      {healthData && (
        <Card>
          <CardHeader>
            <CardTitle className="text-lg">Health Details</CardTitle>
          </CardHeader>
          <CardContent className="space-y-2">
            <div className="flex justify-between text-sm">
              <span className="text-foreground-muted">Platform</span>
              <span className="font-medium">{healthData.platform || '—'}</span>
            </div>
            <div className="flex justify-between text-sm">
              <span className="text-foreground-muted">Version</span>
              <span className="font-medium">{healthData.version || '—'}</span>
            </div>
            <div className="flex justify-between text-sm">
              <span className="text-foreground-muted">Timestamp</span>
              <span className="font-medium">{healthData.timestamp ? new Date(healthData.timestamp).toLocaleString() : '—'}</span>
            </div>
            <div className="flex justify-between text-sm">
              <span className="text-foreground-muted">Consolidation</span>
              <span className="font-medium">{stats.consolidation_complete ? 'Complete' : 'In Progress'}</span>
            </div>
          </CardContent>
        </Card>
      )}
    </div>
  );
}

import { useState, useEffect, useCallback } from 'react';
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Badge } from '@/components/ui/badge';
import { Separator } from '@/components/ui/separator';
import { User, Mail, Shield, Crown, LogOut, Settings as SettingsIcon, Download, RefreshCw } from 'lucide-react';
import { navigate } from '@/router/HashRouter';
import { apiUrl, authHeaders, getApiBase } from '@/config';

interface UserData {
  email?: string;
  name?: string;
  role?: string;
  plan?: string;
}

export function ProfileView() {
  const [user, setUser] = useState<UserData | null>(null);
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [subscription, setSubscription] = useState<{ plan?: string; scansRemaining?: string | number; apiAccess?: string } | null>(null);
  const [subscriptionUnavailable, setSubscriptionUnavailable] = useState(false);

  // simplebeacon-ignore: framework-practices — standard React useEffect hook
  useEffect(() => {
    try {
      const token = localStorage.getItem('sb_token') || localStorage.getItem('auth_token');
      if (token) {
        setIsAuthenticated(true);
        const userData = localStorage.getItem('sb_user');
        if (userData) {
          setUser(JSON.parse(userData));
        }
        // Fetch subscription data from server
        (async () => {
          try {
            const resp = await fetch(apiUrl('/user/subscription'), { headers: authHeaders() });
            if (resp.status === 404) {
              setSubscriptionUnavailable(true);
            }
            if (resp.ok) {
              const body = await resp.json();
              if (body && body.subscription) setSubscription(body.subscription);
            }
          } catch {
            setSubscriptionUnavailable(true);
          }
        })();
      }
    } catch {
      /* ignore */
    }
  }, []);

  const handleSignOut = () => {
    localStorage.removeItem('sb_token');
    localStorage.removeItem('sb_user');
    localStorage.removeItem('auth_token');
    navigate('signin');
  };

  const [exporting, setExporting] = useState(false);

  const handleExport = useCallback(async () => {
    setExporting(true);
    try {
      const profile = user || {};
      const email = profile.email || 'unknown';
      const host = typeof window !== 'undefined' ? (window.location?.hostname || 'localhost') : 'localhost';
      const timestamp = Date.now();

      // Gather data from localStorage
      let scanHistory: unknown[] = [];
      try {
        const raw = localStorage.getItem('sb_scan_history');
        if (raw) scanHistory = JSON.parse(raw);
      } catch { /* ignore */ }

      let report: unknown = null;
      try {
        const raw = localStorage.getItem('sb_last_scan_full');
        if (raw) report = JSON.parse(raw);
      } catch { /* ignore */ }

      let baseline: unknown = null;
      try {
        const raw = localStorage.getItem('sb_baseline');
        if (raw) baseline = JSON.parse(raw);
      } catch { /* ignore */ }

      let config: unknown = null;
      try {
        const raw = localStorage.getItem('sb_config');
        if (raw) config = JSON.parse(raw);
      } catch { /* ignore */ }

      let assessment: unknown = null;
      try {
        const raw = localStorage.getItem('sb_assessment');
        if (raw) assessment = JSON.parse(raw);
      } catch { /* ignore */ }

      // Fetch AI keys from API
      let aiKeys: unknown = null;
      try {
        const resp = await fetch(apiUrl('/simplebeacon/user/ai-keys'), { headers: authHeaders() });
        if (resp.ok) aiKeys = await resp.json();
      } catch { /* ignore */ }

      // If scan history is empty, try fetching from API
      if (scanHistory.length === 0) {
        try {
          const resp = await fetch(apiUrl('/simplebeacon/history?limit=50'), { headers: authHeaders() });
          if (resp.ok) {
            const body = await resp.json();
            if (Array.isArray(body)) {
              scanHistory = body;
            } else if (body?.history) {
              scanHistory = body.history;
            }
          }
        } catch { /* ignore */ }
      }

      const bundle = {
        exportedAt: new Date().toISOString(),
        profile: {
          id: (profile as any).id || 'dev-user-01',
          email,
          name: profile.name || 'Local Developer',
          role: profile.role || 'admin',
          tier: (profile as any).tier || null,
          trustLevel: (profile as any).trustLevel || 'platinum',
        },
        aiKeys: aiKeys || {
          email,
          providers: {},
          ollamaBaseUrl: '',
          ollamaModel: '',
          updatedAt: null,
        },
        scanHistory,
        report,
        baseline,
        config,
        assessment,
      };

      const blob = new Blob([JSON.stringify(bundle, null, 2)], { type: 'application/json' });
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = `simplebeacon-export-${host.replace(/[^a-zA-Z0-9]/g, '_')}-${timestamp}.json`;
      a.click();
      URL.revokeObjectURL(url);
    } catch (e) {
      console.error('Export failed:', e);
    } finally {
      setExporting(false);
    }
  }, [user]);

  if (!isAuthenticated) {
    return (
      <div className="mx-auto max-w-4xl p-6 space-y-6">
        <div className="flex flex-col gap-2">
          <h1 className="text-3xl font-bold tracking-tight">Profile</h1>
          <p className="text-foreground-muted">Account settings and preferences</p>
        </div>
        <Card>
          <CardContent className="flex flex-col items-center gap-3 py-12">
            <User className="h-12 w-12 text-foreground-muted" />
            <p className="text-sm text-foreground-muted">Sign in to view your profile</p>
            <Button onClick={() => navigate('signin')}>Sign In</Button>
          </CardContent>
        </Card>
      </div>
    );
  }

  const displayName = user?.name || user?.email || 'User';
  const initials = displayName.charAt(0).toUpperCase();
  const plan = user?.plan || 'free';
  const role = user?.role || 'user';
  const displayedPlan = subscription?.plan || plan;

  return (
    <div className="mx-auto max-w-4xl p-6 space-y-6">
      <div className="flex flex-col gap-2">
        <h1 className="text-3xl font-bold tracking-tight">Profile</h1>
        <p className="text-foreground-muted">Account settings and preferences</p>
      </div>

      {/* User Identity Card */}
      <Card>
        <CardContent className="flex items-center gap-4 py-6">
          <div className="flex h-16 w-16 shrink-0 items-center justify-center rounded-full bg-primary text-xl font-bold text-primary-foreground">
            {initials}
          </div>
          <div className="flex flex-col gap-1">
            <div className="flex items-center gap-2">
              <h2 className="text-xl font-semibold">{displayName}</h2>
              {plan !== 'free' && (
                <Badge className="gap-1">
                  <Crown className="h-3 w-3" /> {plan}
                </Badge>
              )}
              {role !== 'user' && (
                <Badge variant="outline" className="gap-1">
                  <Shield className="h-3 w-3" /> {role}
                </Badge>
              )}
            </div>
            {user?.email && (
              <div className="flex items-center gap-1.5 text-sm text-foreground-muted">
                <Mail className="h-3.5 w-3.5" /> {user.email}
              </div>
            )}
          </div>
        </CardContent>
      </Card>

      {/* Subscription / Tier Card */}
      <Card>
        <CardHeader>
          <CardTitle>Subscription</CardTitle>
          <CardDescription>Current plan and usage</CardDescription>
        </CardHeader>
        <CardContent className="space-y-4">
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-2">
              <span className="text-sm font-medium">Plan</span>
              <Badge variant={plan === 'free' ? 'secondary' : 'default'} className="capitalize">
                {displayedPlan}
              </Badge>
            </div>
            {displayedPlan === 'free' && (
              <Button size="sm" onClick={() => subscriptionUnavailable ? navigate('help') : navigate('settings')}>
                <Crown className="h-4 w-4" /> Upgrade
              </Button>
            )}
          </div>
          <Separator />
          <div className="flex items-center justify-between">
            <span className="text-sm text-foreground-muted">Scans remaining</span>
            <span className="text-sm font-medium">{subscription?.scansRemaining ?? 'Unlimited'}</span>
          </div>
          <div className="flex items-center justify-between">
            <span className="text-sm text-foreground-muted">API access</span>
            <span className="text-sm font-medium">{subscription?.apiAccess ?? (plan === 'free' ? 'Limited' : 'Full')}</span>
          </div>
        </CardContent>
      </Card>

      {/* Preferences Card */}
      <Card>
        <CardHeader>
          <CardTitle>Preferences</CardTitle>
          <CardDescription>Manage dashboard and scan preferences</CardDescription>
        </CardHeader>
        <CardContent className="space-y-3">
          <div className="flex items-center justify-between rounded-md border border-border px-4 py-3">
            <div className="flex items-center gap-3">
              <SettingsIcon className="h-4 w-4 text-foreground-muted" />
              <div>
                <p className="text-sm font-medium">Dashboard Settings</p>
                <p className="text-xs text-foreground-muted">API keys, scan paths, AI providers</p>
              </div>
            </div>
            <Button variant="outline" size="sm" onClick={() => navigate('settings')}>
              Open
            </Button>
          </div>
        </CardContent>
      </Card>

      {/* Account Actions Card */}
      <Card>
        <CardHeader>
          <CardTitle>Account Actions</CardTitle>
          <CardDescription>Manage your account data</CardDescription>
        </CardHeader>
        <CardContent className="space-y-3">
          <div className="flex items-center justify-between rounded-md border border-border px-4 py-3">
            <div className="flex items-center gap-3">
              <Download className="h-4 w-4 text-foreground-muted" />
              <div>
                <p className="text-sm font-medium">Export Data</p>
                <p className="text-xs text-foreground-muted">Download your scan history and reports</p>
              </div>
            </div>
            <Button
              variant="outline"
              size="sm"
              disabled={exporting}
              onClick={handleExport}
            >
              {exporting ? <><RefreshCw className="h-4 w-4 animate-spin" /> Exporting…</> : <><Download className="h-4 w-4" /> Export</>}
            </Button>
          </div>
          <div className="flex items-center justify-between rounded-md border border-danger/30 px-4 py-3">
            <div className="flex items-center gap-3">
              <LogOut className="h-4 w-4 text-danger" />
              <div>
                <p className="text-sm font-medium">Sign Out</p>
                <p className="text-xs text-foreground-muted">End your current session</p>
              </div>
            </div>
            <Button variant="outline" size="sm" onClick={handleSignOut}>
              Sign Out
            </Button>
          </div>
        </CardContent>
      </Card>
    </div>
  );
}

import { Card, CardContent, CardHeader, CardTitle, CardDescription } from '@/components/ui/card';
import { Badge } from '@/components/ui/badge';
import { Button } from '@/components/ui/button';
import { Award, FileCode, AlertTriangle, Shield, CheckCircle2, Play, Info, TrendingUp, Download } from 'lucide-react';
import { useEffect, useState } from 'react';
import { navigate } from '@/router/HashRouter';

interface ScanResultData {
  totalFiles: number;
  issueCount: number;
  severityCounts: { critical: number; high: number; medium: number; low: number; info: number };
  gate: { pass: boolean; blockingCount: number; warningCount: number };
  qualityScore: number | null;
  projectPath: string;
  scanScope: { profile: string; resultsViewScope: string; codeFilesAnalyzed: number };
}

export function QualityView() {
  const [result, setResult] = useState<ScanResultData | null>(null);
  const [scanTime, setScanTime] = useState<string | null>(null);

  useEffect(() => {
    try {
      const full = localStorage.getItem('sb_last_scan_full');
      if (full) setResult(JSON.parse(full));
      const time = localStorage.getItem('sb_last_scan_time');
      if (time) setScanTime(new Date(time).toLocaleString());
    } catch {
      /* ignore */
    }
  }, []);

  const exportQuality = () => {
    const payload = {
      exportedAt: new Date().toISOString(),
      scan: result || {
        totalFiles: 0,
        issueCount: 0,
        severityCounts: { critical: 0, high: 0, medium: 0, low: 0, info: 0 },
        gate: { pass: true, blockingCount: 0, warningCount: 0 },
        qualityScore: 100,
        projectPath: '',
        scanScope: { profile: 'unknown', resultsViewScope: 'quality', codeFilesAnalyzed: 0 },
      },
      scanTime,
    };
    const blob = new Blob([JSON.stringify(payload, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    const root = ((result && result.projectPath) || 'quality').replace(/[\/:\\\s]+/g, '-').slice(0, 60);
    a.href = url;
    a.download = `quality-${root || 'quality'}-${new Date().toISOString().replace(/[:.]/g, '-')}.json`;
    document.body.appendChild(a);
    a.click();
    a.remove();
    URL.revokeObjectURL(url);
  };

  if (!result) {
    return (
      <div className="mx-auto max-w-5xl p-6 space-y-6">
        <div className="flex flex-col gap-2">
          <h1 className="text-3xl font-bold tracking-tight">Quality</h1>
          <p className="text-foreground-muted">Code quality metrics and trends</p>
        </div>
        <Card>
          <CardContent className="flex flex-col items-center gap-3 py-16">
            <Award className="h-12 w-12 text-foreground-muted" />
            <p className="text-sm text-foreground-muted">No quality metrics to display</p>
            <p className="text-xs text-foreground-muted">Run a scan from the Analyze page to see quality metrics</p>
            <div className="mt-2 flex gap-2">
              <Button onClick={() => navigate('analyze')}>
                <Play className="h-4 w-4 mr-2" /> Go to Analyze
              </Button>
              <Button variant="outline" onClick={exportQuality}>
                <Download className="h-4 w-4 mr-2" /> Export JSON
              </Button>
            </div>
          </CardContent>
        </Card>
      </div>
    );
  }

  const sev = result.severityCounts || { critical: 0, high: 0, medium: 0, low: 0, info: 0 };
  const score = result.qualityScore ?? 0;
  const gatePass = result.gate?.pass ?? false;
  const codeFiles = result.scanScope?.codeFilesAnalyzed ?? 0;

  const severityItems = [
    { label: 'Critical', value: sev.critical || 0, color: 'text-red-500', bg: 'bg-red-500/10' },
    { label: 'High', value: sev.high || 0, color: 'text-orange-500', bg: 'bg-orange-500/10' },
    { label: 'Medium', value: sev.medium || 0, color: 'text-yellow-500', bg: 'bg-yellow-500/10' },
    { label: 'Low', value: sev.low || 0, color: 'text-blue-500', bg: 'bg-blue-500/10' },
    { label: 'Info', value: sev.info || 0, color: 'text-gray-500', bg: 'bg-gray-500/10' },
  ];

  return (
    <div className="mx-auto max-w-5xl p-6 space-y-6">
