        </CardHeader>
        <CardContent className="space-y-3">
          {severityItems.map((item) => {
            const maxVal = Math.max(...severityItems.map((s) => s.value), 1);
            const pct = (item.value / maxVal) * 100;
            return (
              <div key={item.label} className="flex items-center gap-3">
