import { useState, useEffect, useCallback } from 'react';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Badge } from '@/components/ui/badge';
import { Button } from '@/components/ui/button';
import { Map, RefreshCw, AlertCircle, CheckCircle2, Circle, Clock, AlertTriangle, ListTodo, TrendingUp, Zap, Download } from 'lucide-react';
import { getApiBase, apiUrl, authHeaders } from '@/config';
import { navigate } from '@/router/HashRouter';

type Phase = {
  phase?: string;
  name?: string;
  status?: string;
  items?: string[];
  features?: Array<{ name: string; status: string; category?: string }>;
};

type Risk = {
  category?: string;
  severity?: string;
  description?: string;
};

type ActionItem = {
  priority?: string;
  action?: string;
  category?: string;
  description?: string;
};

type Recommendation = {
  priority?: string;
  action?: string;
  description?: string;
  effort?: string;
  risk?: string;
  savings?: string;
};

type RoadmapData = {
  type?: string;
  generatedAt?: string;
  projectName?: string;
  executiveSummary?: {
    totalFeatures?: number;
    completedFeatures?: number;
    inProgressFeatures?: number;
    plannedFeatures?: number;
    completionRate?: number;
    projectHealth?: string;
    notes?: string;
    lastUpdated?: string;
  };
  developmentPhases?: Phase[];
  implementationPhases?: Phase[];
  risks?: Risk[];
  actionPlan?: ActionItem[];
  recommendations?: Recommendation[];
  progressMetrics?: {
    completionRate?: number;
    totalFeatures?: number;
    completedFeatures?: number;
    [key: string]: unknown;
  };
  sourceProjectPath?: string;
};

function statusIcon(status?: string) {
  const s = typeof status === 'string' && status ? status.toLowerCase() : 'pending';
  if (s === 'complete' || s === 'completed' || s === 'done') return <CheckCircle2 className="h-4 w-4 text-green-500" />;
  if (s === 'active' || s === 'in-progress' || s === 'in progress') return <Clock className="h-4 w-4 text-blue-500" />;
  if (s === 'planned' || s === 'pending' || s === 'not-started') return <Circle className="h-4 w-4 text-foreground-muted" />;
  if (s === 'blocked') return <AlertTriangle className="h-4 w-4 text-red-500" />;
  return <Circle className="h-4 w-4 text-foreground-muted" />;
}

function statusColor(status?: string): string {
  const s = typeof status === 'string' && status ? status.toLowerCase() : 'pending';
  if (s === 'complete' || s === 'completed' || s === 'done') return 'bg-green-500/15 text-green-500 border-green-500/30';
  if (s === 'active' || s === 'in-progress' || s === 'in progress') return 'bg-blue-500/15 text-blue-500 border-blue-500/30';
  if (s === 'blocked') return 'bg-red-500/15 text-red-500 border-red-500/30';
  if (s === 'planned' || s === 'pending') return 'bg-gray-500/15 text-gray-500 border-gray-500/30';
  return 'bg-gray-500/15 text-gray-500 border-gray-500/30';
}

function priorityColor(priority?: string): string {
  const p = typeof priority === 'string' && priority ? priority.toLowerCase() : '';
  if (p === 'critical' || p === 'high') return 'bg-red-500/15 text-red-500 border-red-500/30';
  if (p === 'medium') return 'bg-yellow-500/15 text-yellow-500 border-yellow-500/30';
  if (p === 'low') return 'bg-blue-500/15 text-blue-500 border-blue-500/30';
  return 'bg-gray-500/15 text-gray-500 border-gray-500/30';
}

export function RemediationView() {
  const [data, setData] = useState<RoadmapData | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const apiBase = getApiBase();

  const fetchData = useCallback(async () => {
    setLoading(true);
    setError(null);
    try {
      let projectPath = 'CascadeProjects';
      try {
        const stored = localStorage.getItem('sb_last_scan_full');
        if (stored) {
          const scan = JSON.parse(stored);
          if (scan?.projectPath) projectPath = scan.projectPath;
        }
      } catch { /* ignore */ }

      const resp = await fetch(apiUrl('/analyze/flexible'), {
        method: 'POST',
        headers: { 'Content-Type': 'application/json', ...authHeaders() },
        body: JSON.stringify({ projectPath, analysisType: 'roadmap' }),
      });
      if (!resp.ok) throw new Error(`Server returned ${resp.status}`);
      const json = await resp.json();
      const roadmap = json.roadmap || json.report?._roadmapAnalysis || json.report || json;
      setData(roadmap);
    } catch (e: any) {
      setError(e?.message || 'Failed to fetch remediation roadmap');
    } finally {
      setLoading(false);
    }
  }, [apiBase]);

  // simplebeacon-ignore: framework-practices
  useEffect(() => { void fetchData(); }, [fetchData]);

  const fmtDate = (s?: string) => {
    if (!s) return '—';
    try { return new Date(s).toLocaleString(); } catch { return s; }
  };

  const exportRoadmap = () => {
    if (!data) return;
    const payload = { exportedAt: new Date().toISOString(), roadmap: data };
    const blob = new Blob([JSON.stringify(payload, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    const root = (data.sourceProjectPath || data.projectName || 'roadmap').replace(/[\/:\\\s]+/g, '-').slice(0, 60);
    a.href = url;
    a.download = `remediation-${root || 'roadmap'}-${new Date().toISOString().replace(/[:.]/g, '-')}.json`;
    document.body.appendChild(a);
    a.click();
    a.remove();
    URL.revokeObjectURL(url);
  };

  if (loading) {
    return (
      <div className="mx-auto max-w-5xl p-6 space-y-6">
        <div className="flex flex-col gap-2">
          <h1 className="text-3xl font-bold tracking-tight">Remediation</h1>
          <p className="text-foreground-muted">Prioritized fix roadmap and remediation tracking</p>
        </div>
        <Card>
          <CardContent className="flex flex-col items-center gap-3 py-12">
            <RefreshCw className="h-8 w-8 text-foreground-muted animate-spin" />
            <p className="text-sm text-foreground-muted">Generating remediation roadmap…</p>
          </CardContent>
        </Card>
      </div>
    );
  }

  if (error && !data) {
    return (
      <div className="mx-auto max-w-5xl p-6 space-y-6">
        <div className="flex flex-col gap-2">
          <h1 className="text-3xl font-bold tracking-tight">Remediation</h1>
          <p className="text-foreground-muted">Prioritized fix roadmap and remediation tracking</p>
        </div>
        <Card>
          <CardContent className="flex flex-col items-center gap-3 py-12">
            <AlertCircle className="h-12 w-12 text-foreground-muted" />
            <p className="text-sm text-foreground-muted">{error}</p>
            <Button size="sm" onClick={() => fetchData()} className="mt-2">
              <RefreshCw className="h-4 w-4 mr-2" /> Retry
            </Button>
          </CardContent>
        </Card>
      </div>
    );
  }

  if (!data) {
    return (
      <div className="mx-auto max-w-5xl p-6 space-y-6">
        <div className="flex flex-col gap-2">
          <h1 className="text-3xl font-bold tracking-tight">Remediation</h1>
          <p className="text-foreground-muted">Prioritized fix roadmap and remediation tracking</p>
        </div>
        <Card>
          <CardContent className="flex flex-col items-center gap-3 py-8">
            <Map className="h-12 w-12 text-foreground-muted" />
            <p className="text-sm text-foreground-muted">No remediation roadmap available</p>
            <Button onClick={() => navigate('analyze')} className="mt-2">Start a Scan</Button>
          </CardContent>
        </Card>
      </div>
    );
  }

  const summary = data.executiveSummary || {};
  const phases = data.developmentPhases || data.implementationPhases || [];
  const risks = data.risks || [];
  const actionPlan = data.actionPlan || [];
  const recommendations = data.recommendations || [];
  const completionRate = summary.completionRate ?? data.progressMetrics?.completionRate ?? 0;

  return (
    <div className="mx-auto max-w-5xl p-6 space-y-6">
      <div className="flex items-start justify-between">
        <div className="flex flex-col gap-2">
          <h1 className="text-3xl font-bold tracking-tight">Remediation</h1>
          <p className="text-foreground-muted">Prioritized fix roadmap and remediation tracking</p>
          {data.sourceProjectPath && (
            <p className="text-xs text-foreground-muted">{data.sourceProjectPath} — {fmtDate(data.generatedAt)}</p>
          )}
        </div>
        <div className="ml-4 flex items-center gap-2">
          <Button size="sm" variant="outline" onClick={exportRoadmap}>
            <Download className="h-4 w-4 mr-2" /> Export JSON
          </Button>
        </div>
      </div>

      {/* Executive Summary */}
      <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
        <Card>
          <CardContent className="flex flex-col items-center gap-1 py-4">
