      )}

      {/* Top Categories */}
      {topCategories.length > 0 && (
        <Card>
          <CardHeader>
            <CardTitle className="text-base">Issue Categories</CardTitle>
          </CardHeader>
          <CardContent>
            <div className="space-y-2">
              {topCategories.map((cat) => (
                <div key={cat.category} className="flex items-center justify-between rounded-md border px-3 py-2">
                  <div className="flex items-center gap-2">
                    <Badge variant={cat.severity === 'critical' || cat.severity === 'high' ? 'destructive' : 'outline'} className="text-xs">
                      {cat.severity}
                    </Badge>
                    <span className="text-sm font-medium">{cat.label || cat.category}</span>
                  </div>
                  <div className="flex items-center gap-3 text-xs text-foreground-muted">
                    <span>{cat.count} findings</span>
                    <span>{cat.fileCount} files</span>
                  </div>
                </div>
              ))}
            </div>
          </CardContent>
        </Card>
      )}

      {/* Tier Distribution */}
      {s.tierCounts && Object.keys(s.tierCounts).length > 0 && (
