import { useState, useEffect } from 'react';
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from '@/components/ui/card';
import { Badge } from '@/components/ui/badge';
import { Button } from '@/components/ui/button';
import { Separator } from '@/components/ui/separator';
import { Tabs, TabsList, TabsTrigger, TabsContent } from '@/components/ui/tabs';
import { ClipboardList, Download, FileCode, AlertTriangle, Shield, CheckCircle2, Play, Info } from 'lucide-react';
import { navigate } from '@/router/HashRouter';

interface ScanResultData {
  totalFiles: number;
  issueCount: number;
  severityCounts: { critical: number; high: number; medium: number; low: number; info: number };
  gate: { pass: boolean; blockingCount: number; warningCount: number };
  qualityScore: number | null;
  projectPath: string;
  scanScope: { profile: string; resultsViewScope: string; codeFilesAnalyzed: number };
}

export function ResultsView() {
  const [filter, setFilter] = useState<string>('all');
  const [result, setResult] = useState<ScanResultData | null>(null);
  const [scanTime, setScanTime] = useState<string | null>(null);

  // simplebeacon-ignore: framework-practices — standard React useEffect hook
  useEffect(() => {
    try {
      const full = localStorage.getItem('sb_last_scan_full');
      if (full) {
        setResult(JSON.parse(full));
      }
      const time = localStorage.getItem('sb_last_scan_time');
      if (time) {
        setScanTime(new Date(time).toLocaleString());
      }
    } catch {
      /* ignore */
    }
  }, []);

  if (!result) {
    return (
      <div className="mx-auto max-w-7xl p-6 space-y-6">
        <div className="flex flex-col gap-2">
          <h1 className="text-3xl font-bold tracking-tight">Results</h1>
          <p className="text-foreground-muted">Detailed scan findings and issue breakdown</p>
        </div>
        <Card>
          <CardContent className="flex flex-col items-center gap-3 py-16">
            <ClipboardList className="h-12 w-12 text-foreground-muted" />
            <p className="text-sm text-foreground-muted">No scan results loaded</p>
            <p className="text-xs text-foreground-muted">Run a scan from the Analyze page to see results here</p>
            <Button className="mt-2" onClick={() => navigate('analyze')}>
              <Play className="h-4 w-4" /> Go to Analyze
            </Button>
          </CardContent>
        </Card>
      </div>
    );
  }

  const severities = ['critical', 'high', 'medium', 'low', 'info'] as const;
  const activeSeverities = severities.filter(s => result.severityCounts[s] > 0);

  return (
    <div className="mx-auto max-w-7xl p-6 space-y-6">
      <div className="flex flex-col gap-2">
        <h1 className="text-3xl font-bold tracking-tight">Results</h1>
        <p className="text-foreground-muted">Detailed scan findings and issue breakdown</p>
      </div>

      {/* Overview Card */}
      <Card>
        <CardHeader>
          <div className="flex items-center justify-between">
            <div>
              <CardTitle>Scan Report</CardTitle>
              <CardDescription>
                {result.projectPath}
                {scanTime && <span className="ml-2 text-xs">— {scanTime}</span>}
              </CardDescription>
            </div>
            <Badge variant={result.gate.pass ? 'success' : 'danger'} className="text-sm">
              {result.gate.pass ? 'PASS' : 'FAIL'}
            </Badge>
          </div>
        </CardHeader>
        <CardContent className="space-y-4">
          <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-4">
            <MetricCard icon={FileCode} label="Files Scanned" value={result.totalFiles} />
            <MetricCard icon={AlertTriangle} label="Issues Found" value={result.issueCount} />
            <MetricCard icon={Shield} label="Rules Checked" value={result.scanScope.codeFilesAnalyzed || 0} />
            <MetricCard icon={CheckCircle2} label="Quality Score" value={result.qualityScore !== null ? `${result.qualityScore}%` : '—'} />
          </div>

          <Separator />

          <div className="flex flex-wrap gap-2">
            {severities.map((sev) => (
              <Badge
                key={sev}
                variant={
                  sev === 'critical' ? 'danger' :
                  sev === 'high' ? 'warning' :
                  sev === 'medium' ? 'info' :
                  sev === 'low' ? 'secondary' : 'outline'
                }
                className="capitalize gap-1.5"
              >
                {sev}: {result.severityCounts[sev]}
              </Badge>
            ))}
          </div>
        </CardContent>
      </Card>

      {/* Severity Filter + Detail Tabs */}
      <Tabs defaultValue="summary">
        <TabsList>
          <TabsTrigger value="summary">Summary</TabsTrigger>
          <TabsTrigger value="scope">Scope</TabsTrigger>
          <TabsTrigger value="export">Export</TabsTrigger>
        </TabsList>

        <TabsContent value="summary">
          <Card>
            <CardHeader>
              <CardTitle>Findings Breakdown</CardTitle>
              <CardDescription>Issues grouped by severity</CardDescription>
            </CardHeader>
            <CardContent className="space-y-3">
              <div className="flex flex-wrap gap-2 mb-2">
                {['all', ...activeSeverities].map((sev) => (
                  <Button
                    key={sev}
                    variant={filter === sev ? 'default' : 'outline'}
                    size="sm"
                    onClick={() => setFilter(sev)}
                    className="capitalize"
                  >
                    {sev}
                    {sev !== 'all' && sev !== 'info' && (
                      <span className="ml-1.5 text-xs opacity-70">
                        {result.severityCounts[sev as keyof typeof result.severityCounts]}
                      </span>
                    )}
                  </Button>
                ))}
              </div>

              <Separator />

              {result.issueCount === 0 ? (
                <div className="flex items-center gap-3 py-8">
                  <CheckCircle2 className="h-8 w-8 text-success" />
                  <div>
                    <p className="text-sm font-medium">No issues detected</p>
                    <p className="text-xs text-foreground-muted">All gate rules passed with zero findings</p>
                  </div>
                </div>
              ) : (
                <div className="space-y-2">
                  {severities
                    .filter(s => filter === 'all' || s === filter)
                    .filter(s => result.severityCounts[s] > 0)
                    .map((sev) => (
                      <div key={sev} className="flex items-center justify-between rounded-md border border-border px-4 py-3">
                        <div className="flex items-center gap-3">
                          <Badge
                            variant={
                              sev === 'critical' ? 'danger' :
                              sev === 'high' ? 'warning' :
                              sev === 'medium' ? 'info' :
                              sev === 'low' ? 'secondary' : 'outline'
                            }
                            className="capitalize"
                          >
                            {sev}
                          </Badge>
                          <span className="text-sm text-foreground-muted">
                            {result.severityCounts[sev]} finding{result.severityCounts[sev] !== 1 ? 's' : ''}
                          </span>
                        </div>
                      </div>
                    ))}
                </div>
              )}
            </CardContent>
          </Card>
        </TabsContent>

        <TabsContent value="scope">
          <Card>
            <CardHeader>
              <CardTitle>Scan Scope</CardTitle>
              <CardDescription>Configuration and scope of the last scan</CardDescription>
            </CardHeader>
            <CardContent className="space-y-3">
              <div className="flex items-start gap-3">
                <Info className="h-5 w-5 text-info shrink-0 mt-0.5" />
                <div className="text-sm space-y-1">
                  <p>Repository inventory: <strong>{result.totalFiles} files</strong> indexed</p>
                  <p>Code files analyzed: <strong>{result.scanScope.codeFilesAnalyzed || 0} files</strong></p>
                  <p>Profile: <strong>{result.scanScope.profile}</strong></p>
                  <p>Scope: <strong>{result.scanScope.resultsViewScope}</strong></p>
                  <p>Deterministic gate scan — pattern matching on configured production paths. Source files are not semantically reviewed.</p>
                </div>
              </div>
            </CardContent>
          </Card>
        </TabsContent>

        <TabsContent value="export">
          <Card>
            <CardHeader>
              <CardTitle>Export Results</CardTitle>
              <CardDescription>Download scan report in various formats</CardDescription>
            </CardHeader>
            <CardContent className="flex flex-wrap gap-3">
              <Button variant="outline" size="sm" onClick={() => {
                const blob = new Blob([JSON.stringify(result, null, 2)], { type: 'application/json' });
                const url = URL.createObjectURL(blob);
                const a = document.createElement('a');
                a.href = url;
                a.download = `simplebeacon-report-${Date.now()}.json`;
                a.click();
                URL.revokeObjectURL(url);
              }}>
                <Download className="h-4 w-4" /> JSON Report
              </Button>
              <Button variant="outline" size="sm" onClick={() => navigate('audit')}>
                <Download className="h-4 w-4" /> Audit PDF
              </Button>
              <Button variant="outline" size="sm" onClick={() => navigate('remediation')}>
                <Download className="h-4 w-4" /> Remediation Roadmap
              </Button>
            </CardContent>
          </Card>
        </TabsContent>
      </Tabs>
    </div>
  );
}

// simplebeacon-ignore: mega-params — only 3 params, false positive
function MetricCard({ icon: Icon, label, value }: { icon: React.ComponentType<{ className?: string }>; label: string; value: number | string }) {
  return (
    <div className="flex items-center gap-2">
      <div className="flex h-8 w-8 items-center justify-center rounded-md bg-muted">
        <Icon className="h-4 w-4" />
      </div>
      <div className="flex flex-col">
        <span className="text-xs text-foreground-muted">{label}</span>
        <span className="text-lg font-bold">{value}</span>
      </div>
    </div>
  );
}

import { useState, useEffect, useCallback } from 'react';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Badge } from '@/components/ui/badge';
import { Button } from '@/components/ui/button';
import { Shield, ShieldAlert, ShieldCheck, RefreshCw, AlertCircle, Bug, Lock, FileWarning, Database, KeyRound } from 'lucide-react';
import { getApiBase, apiUrl, authHeaders } from '@/config';

type ScanResultData = {
  projectPath?: string;
  totalFiles?: number;
  issueCount?: number;
  qualityScore?: number;
  severityCounts?: Record<string, number>;
  categories?: Array<{
    category: string;
    label?: string;
    count: number;
    severity: string;
    fileCount?: number;
    topFiles?: string[];
  }>;
  scanScope?: {
    profile?: string;
    codeFilesAnalyzed?: number;
  };
  gate?: {
    pass?: boolean;
    blockingCount?: number;
    warningCount?: number;
  };
  timestamp?: string;
};

type NpmAuditData = {
  vulnerabilities?: {
    total?: number;
    bySeverity?: Record<string, number>;
  };
  advisories?: Array<{
    id?: string;
    title?: string;
    severity?: string;
    package?: string;
    vulnerableVersions?: string;
    patchedVersions?: string;
    url?: string;
  }>;
  metadata?: {
    vulnerabilities?: Record<string, number>;
  };
};

const SECURITY_CATEGORIES = new Set([
  'database-patterns',
  'prototype-pollution',
  'token-bleed',
  'config-drift',
  'credentials',
  'production-leak',
  'security-patterns',
  'security-headers',
  'Broken or invalid files',
  'broken-or-invalid',
]);

function severityColor(sev: string): string {
  switch (sev.toLowerCase()) {
    case 'critical': return 'bg-red-500/15 text-red-500 border-red-500/30';
    case 'high': return 'bg-orange-500/15 text-orange-500 border-orange-500/30';
    case 'medium': return 'bg-yellow-500/15 text-yellow-500 border-yellow-500/30';
    case 'low': return 'bg-blue-500/15 text-blue-500 border-blue-500/30';
    default: return 'bg-gray-500/15 text-gray-500 border-gray-500/30';
  }
}

function categoryIcon(cat: string) {
  const c = cat.toLowerCase();
  if (c.includes('database')) return <Database className="h-4 w-4" />;
  if (c.includes('token') || c.includes('credential')) return <KeyRound className="h-4 w-4" />;
  if (c.includes('broken') || c.includes('invalid')) return <FileWarning className="h-4 w-4" />;
  if (c.includes('prototype') || c.includes('pollution')) return <ShieldAlert className="h-4 w-4" />;
  return <Lock className="h-4 w-4" />;
}

export function SecurityView() {
  const [scanData, setScanData] = useState<ScanResultData | null>(null);
  const [npmAudit, setNpmAudit] = useState<NpmAuditData | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const apiBase = getApiBase();

  const fetchData = useCallback(async () => {
    setLoading(true);
    setError(null);

    // Load last scan summary from localStorage for basic info (projectPath, gate, etc.)
    let scan: ScanResultData | null = null;
    try {
      const stored = localStorage.getItem('sb_last_scan_full');
      if (stored) scan = JSON.parse(stored);
    } catch { /* ignore */ }

    // Fetch codebase analysis (contains categories with security findings) and npm-audit in parallel
    {
      try {
        const [codebaseResp, npmResp] = await Promise.allSettled([
          fetch(apiUrl('/analyze/flexible'), {
            method: 'POST',
            headers: { 'Content-Type': 'application/json', ...authHeaders() },
            body: JSON.stringify({
              projectPath: scan?.projectPath || 'CascadeProjects',
              analysisType: 'codebase',
            }),
          }),
          fetch(apiUrl('/analyze/flexible'), {
            method: 'POST',
            headers: { 'Content-Type': 'application/json', ...authHeaders() },
            body: JSON.stringify({
              projectPath: scan?.projectPath || 'CascadeProjects',
              analysisType: 'npm-audit',
            }),
          }),
        ]);

        // Parse codebase response for categories
        if (codebaseResp.status === 'fulfilled' && codebaseResp.value.ok) {
          const json = await codebaseResp.value.json();
          const r = json.report || {};
          scan = {
            ...scan,
            ...r,
            projectPath: scan?.projectPath || r.projectPath || r.projectRoot || '',
            categories: r.categories || [],
            severityCounts: r.summary?.severityCounts || scan?.severityCounts || {},
            gate: r.gate || scan?.gate || {},
            totalFiles: r.summary?.repositoryFilesTotal || r.totalFiles || scan?.totalFiles,
            issueCount: r.summary?.findingsTotal || r.issueCount || scan?.issueCount,
            qualityScore: r.summary?.healthScore || r.qualityScore || scan?.qualityScore,
            scanScope: r.scanScope || scan?.scanScope,
            timestamp: r.generatedAt || new Date().toISOString(),
          };
        }

        // Parse npm audit response
        if (npmResp.status === 'fulfilled' && npmResp.value.ok) {
          const json = await npmResp.value.json();
          const r = json.report || json;
          setNpmAudit(r._npmAuditAnalysis || r.npmAudit || r);
        }
      } catch {
        // API errors are non-fatal
      }
    }

    setScanData(scan);
    setLoading(false);
  }, [apiBase]);

  // simplebeacon-ignore: framework-practices
  useEffect(() => { void fetchData(); }, [fetchData]);

  const securityFindings = (scanData?.categories || []).filter(
    (c) => SECURITY_CATEGORIES.has(c.category) || SECURITY_CATEGORIES.has(c.category.toLowerCase())
  );

  const securitySeverityCounts: Record<string, number> = {};
  for (const f of securityFindings) {
    const sev = f.severity || 'info';
    securitySeverityCounts[sev] = (securitySeverityCounts[sev] || 0) + f.count;
  }

  const exportSecurityData = useCallback(() => {
    const payload = {
      exportedAt: new Date().toISOString(),
      scanData,
      npmAudit,
      securityFindings,
      securitySeverityCounts,
    };
    try {
      const blob = new Blob([JSON.stringify(payload, null, 2)], { type: 'application/json' });
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      const name = `security-export-${new Date().toISOString().replace(/[:.]/g, '-')}.json`;
      a.href = url;
      a.download = name;
      document.body.appendChild(a);
      a.click();
      a.remove();
      URL.revokeObjectURL(url);
    } catch (err) {
      // ignore
    }
  }, [scanData, npmAudit, securityFindings, securitySeverityCounts]);

  const totalSecurityFindings = securityFindings.reduce((sum, f) => sum + f.count, 0);
  const vulnTotal = npmAudit?.vulnerabilities?.total ?? npmAudit?.metadata?.vulnerabilities?.total ?? 0;
  const vulnBySev = npmAudit?.vulnerabilities?.bySeverity ?? npmAudit?.metadata?.vulnerabilities ?? {};

  if (loading) {
    return (
      <div className="mx-auto max-w-5xl p-6 space-y-6">
        <div className="flex flex-col gap-2">
          <h1 className="text-3xl font-bold tracking-tight">Security</h1>
          <p className="text-foreground-muted">Security findings and vulnerability assessment</p>
        </div>
        <Card>
          <CardContent className="flex flex-col items-center gap-3 py-12">
            <RefreshCw className="h-8 w-8 text-foreground-muted animate-spin" />
            <p className="text-sm text-foreground-muted">Analyzing security data…</p>
          </CardContent>
        </Card>
      </div>
    );
  }

  return (
    <div className="mx-auto max-w-5xl p-6 space-y-6">
      <div className="flex items-start justify-between">
        <div className="flex flex-col gap-2">
          <h1 className="text-3xl font-bold tracking-tight">Security</h1>
          <p className="text-foreground-muted">Security findings and vulnerability assessment</p>
          {scanData?.projectPath && (
            <p className="text-xs text-foreground-muted">{scanData.projectPath}{scanData.timestamp ? ` — ${new Date(scanData.timestamp).toLocaleString()}` : ''}</p>
          )}
        </div>
        <div className="ml-4">
          <Button size="sm" variant="outline" onClick={() => exportSecurityData()}>
            Export JSON
          </Button>
        </div>
      </div>

      {/* Security Overview */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
        <Card>
          <CardContent className="flex flex-col items-center gap-2 py-6">
            <Shield className="h-8 w-8 text-foreground-muted" />
            <span className="text-3xl font-bold">{totalSecurityFindings}</span>
            <span className="text-xs text-foreground-muted">Security Findings</span>
          </CardContent>
        </Card>
        <Card>
          <CardContent className="flex flex-col items-center gap-2 py-6">
            <Bug className="h-8 w-8 text-foreground-muted" />
            <span className="text-3xl font-bold">{vulnTotal}</span>
            <span className="text-xs text-foreground-muted">NPM Vulnerabilities</span>
          </CardContent>
        </Card>
        <Card>
          <CardContent className="flex flex-col items-center gap-2 py-6">
            <ShieldCheck className="h-8 w-8 text-foreground-muted" />
            <span className="text-3xl font-bold">{scanData?.gate?.pass === true ? 'PASS' : scanData?.gate?.pass === false ? 'FAIL' : '—'}</span>
            <span className="text-xs text-foreground-muted">Gate Status</span>
          </CardContent>
        </Card>
      </div>

      {/* Severity Breakdown */}
      {Object.keys(securitySeverityCounts).length > 0 && (
        <Card>
          <CardHeader>
            <CardTitle className="text-lg">Security Severity Breakdown</CardTitle>
          </CardHeader>
          <CardContent>
            <div className="flex flex-wrap gap-3">
              {['critical', 'high', 'medium', 'low', 'info'].filter((s) => securitySeverityCounts[s]).map((sev) => (
                <div key={sev} className="flex items-center gap-2">
                  <Badge className={severityColor(sev)} variant="outline">{sev}</Badge>
                  <span className="text-sm font-medium">{securitySeverityCounts[sev]}</span>
                </div>
              ))}
            </div>
          </CardContent>
        </Card>
      )}

      {/* Security Findings by Category */}
      {securityFindings.length > 0 && (
        <Card>
          <CardHeader>
            <CardTitle className="text-lg">Security Issue Categories</CardTitle>
          </CardHeader>
          <CardContent className="space-y-3">
            {securityFindings
              .sort((a, b) => {
                const order: Record<string, number> = { critical: 0, high: 1, medium: 2, low: 3, info: 4 };
                return (order[a.severity] ?? 5) - (order[b.severity] ?? 5);
              })
              .map((cat) => (
                <div key={cat.category} className="flex items-center justify-between rounded-lg border p-3">
                  <div className="flex items-center gap-3">
                    {categoryIcon(cat.category)}
                    <div>
                      <p className="text-sm font-medium">{cat.label || cat.category}</p>
                      {cat.fileCount != null && (
                        <p className="text-xs text-foreground-muted">{cat.fileCount} file{cat.fileCount !== 1 ? 's' : ''}</p>
                      )}
                    </div>
                  </div>
                  <div className="flex items-center gap-2">
                    <Badge className={severityColor(cat.severity)} variant="outline">{cat.severity}</Badge>
                    <span className="text-sm font-bold">{cat.count}</span>
                  </div>
                </div>
              ))}
          </CardContent>
        </Card>
      )}

      {/* NPM Audit */}
      {vulnTotal > 0 && (
        <Card>
          <CardHeader>
            <CardTitle className="text-lg">Dependency Vulnerabilities (npm audit)</CardTitle>
          </CardHeader>
          <CardContent className="space-y-4">
            <div className="flex flex-wrap gap-3">
              {['critical', 'high', 'moderate', 'low', 'info'].filter((s) => vulnBySev[s]).map((sev) => (
                <div key={sev} className="flex items-center gap-2">
                  <Badge className={severityColor(sev === 'moderate' ? 'medium' : sev)} variant="outline">{sev}</Badge>
                  <span className="text-sm font-medium">{vulnBySev[sev]}</span>
                </div>
              ))}
            </div>
            {npmAudit?.advisories && npmAudit.advisories.length > 0 && (
              <div className="space-y-2">
                {npmAudit.advisories.slice(0, 20).map((adv, i) => (
                  <div key={adv.id || i} className="rounded-lg border p-3">
                    <div className="flex items-center justify-between">
                      <span className="text-sm font-medium">{adv.title || adv.id || 'Vulnerability'}</span>
                      <Badge className={severityColor(adv.severity || 'info')} variant="outline">{adv.severity || 'info'}</Badge>
                    </div>
                    <div className="mt-1 flex items-center gap-4 text-xs text-foreground-muted">
                      {adv.package && <span>Package: <code className="font-mono">{adv.package}</code></span>}
                      {adv.vulnerableVersions && <span>Affected: <code className="font-mono">{adv.vulnerableVersions}</code></span>}
                      {adv.patchedVersions && <span>Patch: <code className="font-mono">{adv.patchedVersions}</code></span>}
                    </div>
                    {adv.url && (
                      <a href={adv.url} target="_blank" rel="noopener noreferrer" className="mt-1 text-xs text-blue-500 hover:underline">
                        More info →
                      </a>
                    )}
                  </div>
                ))}
                {npmAudit.advisories.length > 20 && (
                  <p className="text-xs text-foreground-muted">Showing 20 of {npmAudit.advisories.length} advisories</p>
                )}
              </div>
            )}
          </CardContent>
        </Card>
      )}

      {/* No data */}
      {totalSecurityFindings === 0 && vulnTotal === 0 && !error && (
        <Card>
          <CardContent className="flex flex-col items-center gap-3 py-12">
            <ShieldCheck className="h-12 w-12 text-green-500" />
            <p className="text-sm font-medium">No security findings detected</p>
            <p className="text-xs text-foreground-muted">Run a scan to see security results</p>
            <Button size="sm" variant="outline" onClick={() => fetchData()} className="mt-2">
              <RefreshCw className="h-4 w-4 mr-2" /> Refresh
            </Button>
          </CardContent>
        </Card>
      )}

      {error && (
        <Card>
          <CardContent className="flex flex-col items-center gap-3 py-12">
            <AlertCircle className="h-12 w-12 text-foreground-muted" />
            <p className="text-sm text-foreground-muted">{error}</p>
            <Button size="sm" onClick={() => fetchData()} className="mt-2">
              <RefreshCw className="h-4 w-4 mr-2" /> Retry
            </Button>
          </CardContent>
        </Card>
      )}
    </div>
  );
}

import { useState } from 'react';
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Separator } from '@/components/ui/separator';
import { LogIn, UserPlus } from 'lucide-react';
import { navigate } from '@/router/HashRouter';
import { toast } from 'sonner';
import { apiUrl, authHeaders, waitForApiBase } from '@/config';

export function SignInView() {
  const [mode, setMode] = useState<'signin' | 'register'>('signin');
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [loading, setLoading] = useState(false);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!email || !password) {
      toast.error('Please enter email and password');
      return;
    }
    setLoading(true);
    try {
      await waitForApiBase();
      const endpoint = mode === 'signin' ? '/auth/login' : '/auth/register';
      const resp = await fetch(apiUrl(endpoint), {
        method: 'POST',
        headers: { 'Content-Type': 'application/json', ...authHeaders() },
        body: JSON.stringify({ email, password }),
      });
      if (!resp.ok) throw new Error(`Auth failed: ${resp.status}`);
      const data = await resp.json();
      if (data.token) {
        localStorage.setItem('sb_token', data.token);
        if (data.user) localStorage.setItem('sb_user', JSON.stringify(data.user));
        toast.success(mode === 'signin' ? 'Signed in' : 'Account created');
        navigate('dashboard');
      } else {
        throw new Error('No token received');
      }
    } catch (err: any) {
      toast.error(err.message || 'Authentication failed');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="flex min-h-screen items-center justify-center bg-background p-6">
      <Card className="w-full max-w-md">
        <CardHeader className="text-center">
          <div className="mx-auto mb-2 flex h-12 w-12 items-center justify-center rounded-lg bg-primary">
            <svg viewBox="0 0 24 24" className="h-7 w-7 text-primary-foreground" fill="none" stroke="currentColor" strokeWidth="2">
              <path d="M12 22s8-4 8-10V5l-8-3-8 3v7c0 6 8 10 8 10z" />
              <polyline points="9 12 12 15 16 10" />
            </svg>
          </div>
          <CardTitle className="text-2xl">
            {mode === 'signin' ? 'Sign In' : 'Create Account'}
          </CardTitle>
          <CardDescription>
            {mode === 'signin' ? 'Sign in to your SimpleBeacon account' : 'Register for a free SimpleBeacon account'}
          </CardDescription>
        </CardHeader>
        <CardContent>
          <form onSubmit={handleSubmit} className="space-y-4">
            <div className="space-y-2">
              <Label htmlFor="email">Email</Label>
              <Input
                id="email"
                type="email"
                placeholder="you@example.com"
                value={email}
                onChange={(e) => setEmail(e.target.value)}
              />
            </div>
            <div className="space-y-2">
              <Label htmlFor="password">Password</Label>
              <Input
                id="password"
                type="password"
                placeholder="••••••••"
                value={password}
                onChange={(e) => setPassword(e.target.value)}
              />
            </div>
            <Button type="submit" className="w-full" disabled={loading}>
              {loading ? (
                <span className="animate-pulse">Loading...</span>
              ) : mode === 'signin' ? (
                <><LogIn className="h-4 w-4" /> Sign In</>
              ) : (
                <><UserPlus className="h-4 w-4" /> Register</>
              )}
            </Button>
          </form>
          <Separator className="my-4" />
          <div className="text-center">
            <Button
              variant="link"
              size="sm"
              onClick={() => setMode(mode === 'signin' ? 'register' : 'signin')}
            >
              {mode === 'signin' ? "Don't have an account? Register" : 'Already have an account? Sign in'}
            </Button>
          </div>
        </CardContent>
      </Card>
    </div>
  );
}

import { useState, useCallback } from 'react';
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Progress } from '@/components/ui/progress';
import { Separator } from '@/components/ui/separator';
import {
  Wrench, RefreshCw, AlertCircle, CheckCircle2, Loader2,
  Trash2, FileText, Database, Shield, Download, Calculator, Zap, Clock,
} from 'lucide-react';
import { toast } from 'sonner';
import { getApiBase, apiUrl, authHeaders } from '@/config';
import { navigate } from '@/router/HashRouter';

type ToolStatus = 'idle' | 'running' | 'done' | 'error';

type ToolDef = {
  id: string;
  name: string;
  description: string;
  icon: typeof Wrench;
  analysisType?: string;
  endpoint?: string;
  method?: 'GET' | 'POST';
  color: string;
};

const TOOLS: ToolDef[] = [
  {
    id: 'data-cleanup',
    name: 'Data Cleanup Scan',
    description: 'Directory bloat, stale data, config sprawl, and privacy findings',
    icon: Trash2,
    analysisType: 'data-cleanup',
    color: 'text-orange-500',
  },
  {
    id: 'file-reduction',
    name: 'File Reduction',
    description: 'Build artifacts, duplicate assets, and unused files (dry-run)',
    icon: FileText,
    analysisType: 'file-reduction',
    color: 'text-blue-500',
  },
  {
    id: 'data-quality',
    name: 'Data Quality Scan',
    description: 'Config drift, env keys, stale data, lineage, and shape drift',
    icon: Database,
    analysisType: 'data-quality',
    color: 'text-purple-500',
  },
  {
    id: 'npm-audit',
    name: 'NPM Audit',
    description: 'Dependency vulnerability scan via npm audit',
    icon: Shield,
    analysisType: 'npm-audit',
    color: 'text-red-500',
  },
  {
    id: 'compliance',
    name: 'Compliance Export',
    description: 'Gate layers, compliance checklist, and audit bundle export',
    icon: Download,
    analysisType: 'compliance',
    color: 'text-green-500',
  },
  {
    id: 'ai-math-audit',
    name: 'AI Math Audit',
    description: 'Detect fabricated metrics and hallucinated KPIs in AI outputs',
    icon: Calculator,
    endpoint: '/analyze/ai-math-audit',
    method: 'POST',
    color: 'text-cyan-500',
  },
  {
    id: 'fix-strategies',
    name: 'Fix Strategies',
    description: 'List supported auto-remediation strategies by finding type',
    icon: Zap,
    endpoint: '/v2/fixes/strategies',
    method: 'GET',
    color: 'text-yellow-500',
  },
];

export function ToolsView() {
  const [runningTool, setRunningTool] = useState<string | null>(null);
  const [toolResults, setToolResults] = useState<Record<string, { status: ToolStatus; data?: unknown; error?: string }>>({});
  const [progress, setProgress] = useState(0);
  const [progressLabel, setProgressLabel] = useState('');
  const apiBase = getApiBase();

  const runTool = useCallback(async (tool: ToolDef) => {
    setRunningTool(tool.id);
    setToolResults(prev => ({ ...prev, [tool.id]: { status: 'running' } }));
    setProgress(10);
    setProgressLabel(`Starting ${tool.name}...`);

    try {
      let projectPath = 'CascadeProjects';
      try {
        const stored = localStorage.getItem('sb_last_scan_full');
        if (stored) {
          const scan = JSON.parse(stored);
          if (scan?.projectPath) projectPath = scan.projectPath;
        }
      } catch { /* ignore */ }

      setProgress(30);
      setProgressLabel(`Running ${tool.name}...`);

      let resp: Response;

      if (tool.endpoint && tool.method === 'GET') {
        resp = await fetch(apiUrl(tool.endpoint), {
          headers: authHeaders(),
        });
      } else if (tool.endpoint && tool.method === 'POST') {
        resp = await fetch(apiUrl(tool.endpoint), {
          method: 'POST',
          headers: { 'Content-Type': 'application/json', ...authHeaders() },
          body: JSON.stringify({ projectPath }),
        });
      } else {
        resp = await fetch(apiUrl('/analyze/flexible'), {
          method: 'POST',
          headers: { 'Content-Type': 'application/json', ...authHeaders() },
          body: JSON.stringify({ projectPath, analysisType: tool.analysisType }),
        });
      }

      setProgress(80);
      setProgressLabel('Processing results...');

      if (!resp.ok) {
        const errBody = await resp.json().catch(() => ({}));
        throw new Error(errBody.error || `Server returned ${resp.status}`);
      }

      const data = await resp.json();
      setProgress(100);
      setProgressLabel('Complete');
      setToolResults(prev => ({ ...prev, [tool.id]: { status: 'done', data } }));
      toast.success(`${tool.name} completed`);
    } catch (e: any) {
      setToolResults(prev => ({ ...prev, [tool.id]: { status: 'error', error: e?.message || 'Failed' } }));
      toast.error(`${tool.name} failed: ${e?.message || 'Unknown error'}`);
    } finally {
      setRunningTool(null);
      setTimeout(() => { setProgress(0); setProgressLabel(''); }, 2000);
    }
  }, []);

  const downloadResult = (toolId: string) => {
    const result = toolResults[toolId];
    if (!result?.data) return;
    const blob = new Blob([JSON.stringify(result.data, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `simplebeacon-${toolId}-${Date.now()}.json`;
    a.click();
    URL.revokeObjectURL(url);
  };

  // Export arbitrary file from server archive by requesting a download endpoint
  const exportArchiveFile = async (filename: string) => {
    try {
      const resp = await fetch(apiUrl(`/archive/download?name=${encodeURIComponent(filename)}`), { headers: authHeaders() });
      if (!resp.ok) throw new Error(`Server returned ${resp.status}`);
      const blob = await resp.blob();
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = filename;
      a.click();
      URL.revokeObjectURL(url);
      toast.success('Export started');
    } catch (err: any) {
      toast.error('Export failed: ' + (err?.message || 'unknown'));
    }
  };

  return (
    <div className="mx-auto max-w-5xl p-6 space-y-6">
      <div className="flex flex-col gap-2">
        <h1 className="text-3xl font-bold tracking-tight">Tools</h1>
        <p className="text-foreground-muted">Advanced scanning tools and utilities</p>
        {!apiBase && (
          <p className="text-xs text-yellow-600">
            No local API server detected — tools will run against the remote backend. Start your local SimpleBeacon server for current data.
          </p>
        )}
      </div>

      {runningTool && (
        <Card>
          <CardContent className="space-y-3 p-4">
            <div className="flex items-center justify-between">
              <span className="text-sm font-medium">{progressLabel}</span>
              <span className="text-sm text-foreground-muted">{progress}%</span>
            </div>
            <Progress value={progress} />
          </CardContent>
        </Card>
      )}

      <div className="grid gap-4 md:grid-cols-2">
        {TOOLS.map((tool) => {
          const result = toolResults[tool.id];
          const isRunning = runningTool === tool.id;
          const Icon = tool.icon;
          return (
            <Card key={tool.id}>
              <CardHeader>
                <div className="flex items-start justify-between">
                  <div className="flex items-center gap-3">
                    <div className="flex h-10 w-10 items-center justify-center rounded-lg bg-muted">
                      <Icon className={`h-5 w-5 ${tool.color}`} />
                    </div>
                    <div>
                      <CardTitle className="text-base">{tool.name}</CardTitle>
                      <CardDescription className="text-xs">{tool.description}</CardDescription>
                    </div>
                  </div>
                  {result?.status === 'done' && (
                    <CheckCircle2 className="h-5 w-5 text-green-500 shrink-0" />
                  )}
                  {result?.status === 'error' && (
                    <AlertCircle className="h-5 w-5 text-red-500 shrink-0" />
                  )}
                </div>
              </CardHeader>
              <CardContent className="space-y-3">
                {result?.status === 'error' && (
                  <p className="text-xs text-red-500">{result.error}</p>
                )}
                {result?.status === 'done' && result.data != null && (
                  <div className="space-y-2">
                    <div className="rounded-md bg-muted p-2 text-xs font-mono max-h-32 overflow-y-auto scrollbar-thin">
                      <pre className="whitespace-pre-wrap">{JSON.stringify(result.data, null, 2).slice(0, 2000)}</pre>
                      {JSON.stringify(result.data).length > 2000 && '...'}
                    </div>
                    <Button size="sm" variant="outline" onClick={() => downloadResult(tool.id)}>
                      <Download className="h-3 w-3" /> Export JSON
                    </Button>
                  </div>
                )}
                <Button
                  size="sm"
                  className="w-full"
                  disabled={isRunning}
                  onClick={() => runTool(tool)}
                >
                  {isRunning ? (
                    <><Loader2 className="h-4 w-4 animate-spin" /> Running...</>
                  ) : result?.status === 'done' ? (
                    <><RefreshCw className="h-4 w-4" /> Re-run</>
                  ) : (
                    <><Wrench className="h-4 w-4" /> Run Tool</>
                  )}
                </Button>
              </CardContent>
            </Card>
          );
        })}
      </div>

      <Separator />

      <Card>
        <CardHeader>
          <CardTitle className="text-base">Quick Actions</CardTitle>
        </CardHeader>
        <CardContent className="flex flex-wrap gap-2">
          <Button variant="outline" size="sm" onClick={() => navigate('analyze')}>
            <Wrench className="h-4 w-4" /> Full Scan
          </Button>
          <Button variant="outline" size="sm" onClick={() => navigate('audit')}>
            <Shield className="h-4 w-4" /> Audit Report
          </Button>
          <Button variant="outline" size="sm" onClick={() => navigate('remediation')}>
            <Clock className="h-4 w-4" /> Remediation Roadmap
          </Button>
          <Button variant="outline" size="sm" onClick={() => navigate('security')}>
            <Shield className="h-4 w-4" /> Security View
          </Button>
          <Button variant="outline" size="sm" onClick={() => exportArchiveFile('simplebeacon-fix-strategies-1785040174360.json')}>
            <Download className="h-4 w-4" /> Export Fix Strategies
          </Button>
          <Button variant="outline" size="sm" onClick={() => exportArchiveFile('security-export-2026-07-26T04-26-28-205Z.json')}>
            <Download className="h-4 w-4" /> Export Security Export
          </Button>
        </CardContent>
      </Card>
    </div>
  );
}

import { useState, useEffect, useCallback } from 'react';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Badge } from '@/components/ui/badge';
import { Button } from '@/components/ui/button';
import { BadgeCheck, ShieldCheck, Activity, FileCheck, TrendingUp, RefreshCw, AlertCircle, Download } from 'lucide-react';
import { getApiBase, apiUrl, authHeaders } from '@/config';

type SeverityCounts = Record<string, number>;

type TrustScope = {
  label: string;
  projectRoot: string;
  generatedAt: string;
  gatePass: boolean;
  qualityScore: number | null;
  issueCount: number;
  severityCounts: SeverityCounts;
  repositoryFilesTotal: number;
  ruleScopedFilesAnalyzed: number;
  schemaChecked: number;
  schemaPassed: number;
  rulesEnabled: string[];
  scopeNote?: string;
};

type TrustVerification = {
  success: boolean;
  type: string;
  generatedAt: string;
  verificationMethod: string;
  platform: TrustScope;
  monorepo: TrustScope;
  headlineSource: string;
  headlineReason: string;
  headline: {
    gatePass: boolean;
    qualityScore: number | null;
    issueCount: number;
    lastScan: string;
    repositoryFilesTotal: number;
    ruleScopedFilesAnalyzed: number;
  };
  disclaimers: string[];
  publishedAt: string | null;
};

type TrustTrend = {
  window: number;
  snapshots: number;
  passRatePercent: number;
  avgQualityScore: number;
  avgIssues: number;
  issueDelta: number;
  qualityDelta: number;
  latest: {
    verificationId: string;
    generatedAt: string;
    gatePass: boolean;
    qualityScore: number;
    issues: number;
  } | null;
};

type TrustHistory = {
  success: boolean;
  count: number;
  trend: TrustTrend;
  entries: Array<{
    recordedAt: string;
    generatedAt: string;
    verificationId: string;
    gatePass: boolean;
    qualityScore: number;
    issues: number;
    source: string;
  }>;
};

export function TrustView() {
  const [verification, setVerification] = useState<TrustVerification | null>(null);
  const [history, setHistory] = useState<TrustHistory | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const apiBase = getApiBase();

  const fetchData = useCallback(async () => {
    setLoading(true);
    setError(null);
    try {
      const [vRes, hRes] = await Promise.all([
        fetch(apiUrl('/trust/verification'), { headers: authHeaders() }),
        fetch(apiUrl('/trust/history?limit=10'), { headers: authHeaders() }),
      ]);
      if (vRes.ok) {
        const vData = await vRes.json();
        setVerification(vData);
      }
      if (hRes.ok) {
        const hData = await hRes.json();
        setHistory(hData);
      }
      if (!vRes.ok && !hRes.ok) {
        setError('Trust API unavailable. Ensure the ai-platform server is running.');
      }
    } catch {
      setError('Failed to fetch trust data. Check your connection to the local server.');
    } finally {
      setLoading(false);
    }
  }, [apiBase]);

  // simplebeacon-ignore: framework-practices
  useEffect(() => { void fetchData(); }, [fetchData]);

  const handlePublish = async () => {
    try {
      const res = await fetch(apiUrl('/trust/publish'), {
        method: 'POST',
        headers: { 'Content-Type': 'application/json', ...authHeaders() },
      });
      if (res.ok) {
        void fetchData();
      }
    } catch {
      // ignore
    }
  };

  const handleDownload = () => {
    if (!verification) return;
    const blob = new Blob([JSON.stringify(verification, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = 'trust-verification.json';
    a.click();
    URL.revokeObjectURL(url);
  };

  const fmtDate = (s: string | null | undefined) => {
    if (!s) return '—';
    try { return new Date(s).toLocaleString(); } catch { return s; }
  };

  const renderScope = (scope: TrustScope, title: string) => {
    if (!scope) return null;
    return (
      <Card>
        <CardHeader className="flex-row items-center justify-between space-y-0">
          <CardTitle className="text-base">{title}</CardTitle>
          <Badge variant={scope.gatePass ? 'default' : 'destructive'}>
            {scope.gatePass ? 'PASS' : 'FAIL'}
          </Badge>
        </CardHeader>
        <CardContent className="space-y-3">
          <div className="grid grid-cols-2 gap-3 text-sm sm:grid-cols-4">
            <div>
              <div className="text-xs text-foreground-muted">Quality Score</div>
              <div className="font-semibold">{scope.qualityScore ?? '—'}</div>
            </div>
            <div>
              <div className="text-xs text-foreground-muted">Issues</div>
              <div className="font-semibold">{scope.issueCount}</div>
            </div>
            <div>
              <div className="text-xs text-foreground-muted">Files Total</div>
              <div className="font-semibold">{scope.repositoryFilesTotal?.toLocaleString() ?? '—'}</div>
            </div>
            <div>
              <div className="text-xs text-foreground-muted">Rules Analyzed</div>
              <div className="font-semibold">{scope.ruleScopedFilesAnalyzed?.toLocaleString() ?? '—'}</div>
            </div>
          </div>
          {scope.severityCounts && Object.keys(scope.severityCounts).length > 0 && (
            <div className="flex flex-wrap gap-2">
              {Object.entries(scope.severityCounts).filter(([,v]) => v > 0).map(([k, v]) => (
                <Badge key={k} variant={k === 'critical' ? 'destructive' : k === 'high' ? 'destructive' : 'outline'}>
                  {k}: {v}
                </Badge>
              ))}
            </div>
          )}
          {scope.rulesEnabled && scope.rulesEnabled.length > 0 && (
            <div>
              <div className="text-xs text-foreground-muted mb-1">Rules Enabled</div>
              <div className="flex flex-wrap gap-1">
                {scope.rulesEnabled.map((r) => (
                  <Badge key={r} variant="secondary" className="text-xs">{r}</Badge>
                ))}
              </div>
            </div>
          )}
          {scope.scopeNote && (
            <p className="text-xs text-foreground-muted">{scope.scopeNote}</p>
          )}
          <div className="text-xs text-foreground-muted">
            Last scan: {fmtDate(scope.generatedAt)}
          </div>
        </CardContent>
      </Card>
    );
  };

  if (loading) {
    return (
      <div className="mx-auto max-w-5xl p-6 space-y-6">
        <div className="flex flex-col gap-2">
          <h1 className="text-3xl font-bold tracking-tight">Trust</h1>
          <p className="text-foreground-muted">Trust verification and integrity attestation</p>
        </div>
        <Card>
          <CardContent className="flex flex-col items-center gap-3 py-12">
            <RefreshCw className="h-8 w-8 text-foreground-muted animate-spin" />
            <p className="text-sm text-foreground-muted">Loading trust data…</p>
          </CardContent>
        </Card>
      </div>
    );
  }

  if (error && !verification) {
    return (
      <div className="mx-auto max-w-5xl p-6 space-y-6">
        <div className="flex flex-col gap-2">
          <h1 className="text-3xl font-bold tracking-tight">Trust</h1>
          <p className="text-foreground-muted">Trust verification and integrity attestation</p>
        </div>
        <Card>
          <CardContent className="flex flex-col items-center gap-3 py-12">
            <AlertCircle className="h-12 w-12 text-foreground-muted" />
            <p className="text-sm text-foreground-muted">{error}</p>
            <Button size="sm" onClick={() => fetchData()} className="mt-2">
              <RefreshCw className="h-4 w-4 mr-2" /> Retry
            </Button>
          </CardContent>
        </Card>
      </div>
    );
  }

  if (!verification) {
    return (
      <div className="mx-auto max-w-5xl p-6 space-y-6">
        <div className="flex flex-col gap-2">
          <h1 className="text-3xl font-bold tracking-tight">Trust</h1>
          <p className="text-foreground-muted">Trust verification and integrity attestation</p>
        </div>
        <Card>
          <CardContent className="flex flex-col items-center gap-3 py-12">
            <BadgeCheck className="h-12 w-12 text-foreground-muted" />
            <p className="text-sm text-foreground-muted">No trust verification data</p>
          </CardContent>
        </Card>
      </div>
    );
  }

  const headline = verification.headline;
  const trend = history?.trend;

  return (
    <div className="mx-auto max-w-5xl p-6 space-y-6">
      <div className="flex flex-col gap-2">
        <h1 className="text-3xl font-bold tracking-tight">Trust</h1>
        <p className="text-foreground-muted">Trust verification and integrity attestation</p>
      </div>

      {/* Headline Summary */}
      <Card>
        <CardHeader className="flex-row items-center justify-between space-y-0">
          <div className="flex items-center gap-2">
            <ShieldCheck className="h-5 w-5" />
            <CardTitle className="text-base">Verification Summary</CardTitle>
          </div>
          <div className="flex items-center gap-2">
            <Button variant="ghost" size="sm" onClick={handleDownload}>
              <Download className="h-4 w-4 mr-1" /> Export
            </Button>
            <Button size="sm" onClick={handlePublish}>
              <RefreshCw className="h-4 w-4 mr-1" /> Publish
            </Button>
            <Button variant="ghost" size="sm" onClick={() => fetchData()}>
              <RefreshCw className="h-4 w-4" />
            </Button>
          </div>
        </CardHeader>
        <CardContent className="space-y-4">
          <div className="grid grid-cols-2 gap-4 sm:grid-cols-4">
            <div className="flex items-center gap-2">
              <BadgeCheck className={`h-8 w-8 ${headline.gatePass ? 'text-green-500' : 'text-red-500'}`} />
              <div>
                <div className="text-xs text-foreground-muted">Gate Status</div>
                <div className="font-semibold">{headline.gatePass ? 'PASS' : 'FAIL'}</div>
              </div>
            </div>
            <div className="flex items-center gap-2">
              <Activity className="h-8 w-8 text-blue-500" />
              <div>
                <div className="text-xs text-foreground-muted">Quality Score</div>
                <div className="font-semibold">{headline.qualityScore ?? '—'}</div>
              </div>
            </div>
            <div className="flex items-center gap-2">
              <FileCheck className="h-8 w-8 text-purple-500" />
              <div>
                <div className="text-xs text-foreground-muted">Issues</div>
                <div className="font-semibold">{headline.issueCount}</div>
              </div>
            </div>
            <div className="flex items-center gap-2">
              <TrendingUp className="h-8 w-8 text-orange-500" />
              <div>
                <div className="text-xs text-foreground-muted">Last Scan</div>
                <div className="font-semibold text-xs">{fmtDate(headline.lastScan)}</div>
              </div>
            </div>
          </div>
          <div className="text-xs text-foreground-muted">
            Verification method: {verification.verificationMethod} · Source: {verification.headlineSource} · {verification.headlineReason}
          </div>
        </CardContent>
      </Card>

      {/* Trend */}
      {trend && trend.latest && (
        <Card>
          <CardHeader>
            <div className="flex items-center gap-2">
              <TrendingUp className="h-5 w-5" />
              <CardTitle className="text-base">Trust Trend</CardTitle>
            </div>
          </CardHeader>
          <CardContent>
            <div className="grid grid-cols-2 gap-4 sm:grid-cols-4 text-sm">
              <div>
                <div className="text-xs text-foreground-muted">Snapshots</div>
                <div className="font-semibold">{trend.snapshots}</div>
              </div>
              <div>
                <div className="text-xs text-foreground-muted">Pass Rate</div>
                <div className="font-semibold">{trend.passRatePercent}%</div>
              </div>
              <div>
                <div className="text-xs text-foreground-muted">Avg Quality</div>
                <div className="font-semibold">{trend.avgQualityScore}</div>
              </div>
              <div>
                <div className="text-xs text-foreground-muted">Avg Issues</div>
                <div className="font-semibold">{trend.avgIssues}</div>
              </div>
            </div>
            {history && history.entries.length > 0 && (
              <div className="mt-4 space-y-2">
                <div className="text-xs text-foreground-muted">Recent Snapshots</div>
                {history.entries.slice(0, 5).map((e) => (
                  <div key={e.verificationId} className="flex items-center justify-between rounded-md border px-3 py-2 text-sm">
                    <div className="flex items-center gap-2">
                      <Badge variant={e.gatePass ? 'default' : 'destructive'} className="text-xs">
                        {e.gatePass ? 'PASS' : 'FAIL'}
                      </Badge>
                      <span className="text-xs text-foreground-muted">{fmtDate(e.generatedAt)}</span>
                    </div>
                    <div className="flex items-center gap-3 text-xs">
                      <span>Q: {e.qualityScore}</span>
                      <span>Issues: {e.issues}</span>
                      <span className="text-foreground-muted">{e.source}</span>
                    </div>
                  </div>
                ))}
              </div>
            )}
          </CardContent>
        </Card>
      )}

      {/* Platform & Monorepo Scopes */}
      <div className="grid gap-4 md:grid-cols-2">
        {verification.platform && renderScope(verification.platform, 'Platform Gate (ai-platform)')}
        {verification.monorepo && renderScope(verification.monorepo, 'Monorepo Root')}
      </div>

      {/* Disclaimers */}
      {verification.disclaimers && verification.disclaimers.length > 0 && (
        <Card>
          <CardHeader>
            <CardTitle className="text-base">Disclaimers</CardTitle>
          </CardHeader>
          <CardContent>
            <ul className="space-y-2 text-xs text-foreground-muted">
              {verification.disclaimers.map((d, i) => (
                <li key={i} className="flex items-start gap-2">
                  <span className="mt-0.5">•</span>
                  <span>{d}</span>
                </li>
              ))}
            </ul>
          </CardContent>
        </Card>
      )}
    </div>
  );
}

import { useState, useRef } from 'react';
import { Card, CardContent } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Upload, FileJson, AlertCircle, CheckCircle2 } from 'lucide-react';
import { navigate } from '@/router/HashRouter';

function normalizeReport(raw: any) {
  const sev = raw?.severityCounts || {};
  const totalFiles = raw?.totalFiles ?? raw?.repositoryFilesTotal ?? 0;
  const issueCount = raw?.issueCount ?? raw?.scan_summary?.total_risks_found ?? 0;
  const blockingCount = (sev.critical ?? 0) + (sev.high ?? 0);
  const warningCount = (sev.medium ?? 0) + (sev.low ?? 0);
  const gatePass = raw?.scan_summary?.status === 'PASSED' && !raw?.scan_summary?.block_merge;

  return {
    totalFiles,
    issueCount,
    severityCounts: {
      critical: sev.critical ?? 0,
      high: sev.high ?? 0,
      medium: sev.medium ?? 0,
      low: sev.low ?? 0,
      info: sev.info ?? 0,
    },
    gate: {
      pass: gatePass,
      blockingCount,
      warningCount,
    },
    qualityScore: raw?.qualityScore ?? null,
    projectPath: raw?.projectRoot || raw?.scanPaths?.[0] || '',
    scanScope: {
      profile: raw?.repositoryInventory?.profile || 'default',
      resultsViewScope: Array.isArray(raw?.scanPaths) ? raw.scanPaths.join('; ') : raw?.projectRoot || '',
      codeFilesAnalyzed: raw?.filesAnalyzed ?? raw?.ruleScopedFilesAnalyzed ?? 0,
    },
  };
}

export function UploadView() {
  const [status, setStatus] = useState<{ type: 'idle' | 'success' | 'error'; message?: string }>({ type: 'idle' });
  const inputRef = useRef<HTMLInputElement>(null);

  const handleFile = (file: File) => {
    if (!file || file.type !== 'application/json' && !file.name.endsWith('.json')) {
      setStatus({ type: 'error', message: 'Please select a JSON report file.' });
      return;
    }
    const reader = new FileReader();
    reader.onload = () => {
      try {
        const raw = JSON.parse(String(reader.result || '{}'));
        if (raw.type !== 'simplebeacon-report' && !raw.scan_summary) {
          setStatus({ type: 'error', message: 'File does not look like a SimpleBeacon report.' });
          return;
        }
        const normalized = normalizeReport(raw);
        localStorage.setItem('sb_last_scan_full', JSON.stringify(normalized));
        localStorage.setItem('sb_last_scan', JSON.stringify({
          files: normalized.totalFiles,
          issues: normalized.issueCount,
          gate: normalized.gate.pass,
        }));
        localStorage.setItem('sb_last_scan_time', raw.generatedAt || new Date().toISOString());
        setStatus({ type: 'success', message: `Loaded report: ${normalized.issueCount} issues, gate ${normalized.gate.pass ? 'PASS' : 'FAIL'}.` });
        setTimeout(() => navigate('results'), 600);
      } catch (e: any) {
        setStatus({ type: 'error', message: e?.message || 'Failed to parse JSON.' });
      }
    };
    reader.onerror = () => setStatus({ type: 'error', message: 'Could not read the selected file.' });
    reader.readAsText(file);
  };

  return (
    <div className="mx-auto max-w-5xl p-6 space-y-6">
      <div className="flex flex-col gap-2">
        <h1 className="text-3xl font-bold tracking-tight">Upload</h1>
        <p className="text-foreground-muted">Upload a SimpleBeacon scan report to view results</p>
      </div>
      <Card>
        <CardContent className="flex flex-col items-center gap-4 py-12">
          <Upload className="h-12 w-12 text-foreground-muted" />
          <p className="text-sm text-foreground-muted">Select a downloaded SimpleBeacon report JSON file</p>
          <input
            ref={inputRef}
            type="file"
            accept="application/json,.json"
            className="hidden"
            onChange={(e) => {
              const file = e.target.files?.[0];
              if (file) handleFile(file);
            }}
          />
          <Button variant="outline" onClick={() => inputRef.current?.click()}>
            <FileJson className="h-4 w-4 mr-2" /> Browse JSON Report
          </Button>
          {status.type === 'error' && (
            <div className="flex items-center gap-2 text-sm text-red-500">
              <AlertCircle className="h-4 w-4" /> {status.message}
            </div>
          )}
          {status.type === 'success' && (
            <div className="flex items-center gap-2 text-sm text-green-500">
              <CheckCircle2 className="h-4 w-4" /> {status.message}
            </div>
          )}
        </CardContent>
      </Card>
    </div>
  );
}
